import React, { useState } from 'react';

const UserInfoTab = ({ userInfo }) => {
  const [isEditing, setIsEditing] = useState(false);
  const [formData, setFormData] = useState(userInfo); // 수정 시 사용할 데이터

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // 여기에 실제 백엔드 회원 정보 수정 API 호출 로직
    alert('회원 정보가 수정되었습니다! (API 연동 필요)');
    console.log('수정된 정보:', formData);
    setIsEditing(false); // 수정 완료 후 보기 모드로 전환
  };

  const handleWithdrawal = () => {
    if (window.confirm('정말 회원 탈퇴하시겠습니까? 모든 정보가 삭제됩니다.')) {
      // 여기에 실제 백엔드 회원 탈퇴 API 호출 로직
      alert('회원 탈퇴가 완료되었습니다. 안녕히 가세요! 👋 (API 연동 필요)');
      // 탈퇴 후 로그인 페이지 등으로 리디렉션
    }
  };

  return (
    <div className="tab-content-section user-info-tab">
      <h3 className="tab-content-title">회원 정보 {!isEditing ? '보기' : '수정'}</h3>

      {!isEditing ? (
        <>
          <div className="info-item">
            <span className="info-label">이름</span>
            <span className="info-value">{userInfo.name}</span>
          </div>
          <div className="info-item">
            <span className="info-label">이메일</span>
            <span className="info-value">{userInfo.email}</span>
          </div>
          <div className="info-item">
            <span className="info-label">회원 등급</span>
            <span className="info-value">{userInfo.membershipLevel}</span>
          </div>
          <div className="info-item">
            <span className="info-label">가입일</span>
            <span className="info-value">{userInfo.registeredDate}</span>
          </div>
          <button className="action-button" onClick={() => setIsEditing(true)}>정보 수정</button>
        </>
      ) : (
        <form onSubmit={handleSubmit}>
          <div className="info-item">
            <label className="info-label" htmlFor="name">이름</label>
            <input
              type="text"
              id="name"
              name="name"
              value={formData.name}
              onChange={handleChange}
              className="info-value-input"
            />
          </div>
          <div className="info-item">
            <label className="info-label" htmlFor="email">이메일</label>
            <input
              type="email"
              id="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              className="info-value-input"
            />
          </div>
          {/* 비밀번호 변경 등 추가 필드 */}
          <div className="button-group">
            <button type="submit" className="action-button">저장</button>
            <button type="button" className="action-button" onClick={() => setIsEditing(false)}>취소</button>
            <button type="button" className="action-button delete-button" onClick={handleWithdrawal}>회원 탈퇴</button>
          </div>
        </form>
      )}
    </div>
  );
};

export default UserInfoTab;
